// Skip automated emails, newsletters, notifications
const item = $input.first().json;

const from = (item.from || '').toLowerCase();
const subject = (item.subject || '').toLowerCase();
const body = (item.text || item.html || '').toLowerCase().substring(0, 500);

const skipPatterns = [
  'noreply', 'no-reply', 'donotreply', 'mailer-daemon',
  'newsletter', 'unsubscribe', 'leiratkozas',
  'notification', 'értesítés', 'alert@', 'notify@',
  'billing@', 'invoice@', 'payment@',
  'n8n-giez', 'hstgr.cloud',  // skip n8n own emails
  'google.com', 'facebook.com', 'instagram.com',
  'linkedin.com', 'twitter.com',
  'postmaster@', 'bounce@', 'spam@'
];

const shouldSkip = skipPatterns.some(p => from.includes(p) || subject.includes(p));

if (shouldSkip) {
  return []; // empty = skip this item
}

// Skip if it's an existing booking notification (from n8n itself)
if (subject.includes('[foglalás]') || subject.includes('[átütemezés]') || subject.includes('[szerkesztett]') || subject.includes('[újragenerált]')) {
  return [];
}

return [{ json: item }];

const geminiResp = $input.first().json;
const originalEmail = $('IMAP Trigger — New Email').first().json;

let classification = {};
try {
  const text = geminiResp.candidates[0].content.parts[0].text;
  // Clean potential markdown code blocks
  const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  classification = JSON.parse(cleaned);
} catch(e) {
  // If parsing fails, assume not a booking request
  classification = { isBookingRequest: false, confidence: 0, summary: 'Parsing error' };
}

// Merge original email data for context
return [{
  json: {
    ...classification,
    originalFrom: originalEmail.from || '',
    originalSubject: originalEmail.subject || '',
    originalBody: (originalEmail.text || originalEmail.html || '').substring(0, 2000),
    emailDate: originalEmail.date || new Date().toISOString(),
    // Fall back to sender email if clientEmail not extracted
    clientEmail: classification.clientEmail || originalEmail.from?.match(/<([^>]+)>/)?.[1] || originalEmail.from || ''
  }
}];

const classif = $('Parse Classification Result').first().json;
const calEvents = $input.all().map(i => i.json);

// Check for conflicts
const requestedDate = classif.requestedDate;
let calendarConflict = false;
let conflictDetails = null;

if (requestedDate && calEvents.length > 0) {
  // Filter out tentative/cancelled events
  const realEvents = calEvents.filter(e => e.status !== 'cancelled');
  if (realEvents.length > 0) {
    calendarConflict = true;
    const eventTitles = realEvents.map(e => e.summary || 'Esemény').join(', ');
    conflictDetails = `Meglévő esemény(ek) a kért napon: ${eventTitles}`;
  }
}

// Map service name to service code
const serviceMap = {
  'esküvő': 'wedding', 'esküvői': 'wedding',
  'portré': 'portrait', 'modell': 'portrait', 'galéria': 'portrait',
  'kismama': 'maternity',
  'boudoir': 'boudoir',
  'család': 'family', 'családi': 'family',
  'páros': 'couple', 'jegyesi': 'couple',
  'kisállat': 'pet',
  'céges': 'business', 'üzleti': 'business', 'arculati': 'business',
  'ingatlan': 'real-estate',
  'termék': 'product',
  'rendezvény': 'event'
};

const svcName = classif.requestedService || 'Fotózás';
let serviceCode = 'portrait'; // default
for (const [key, val] of Object.entries(serviceMap)) {
  if (svcName.toLowerCase().includes(key)) {
    serviceCode = val;
    break;
  }
}

return [{
  json: {
    name: classif.clientName || classif.originalFrom || 'Ismeretlen feladó',
    email: classif.clientEmail,
    phone: classif.clientPhone || '',
    service: serviceCode,
    serviceName: svcName,
    bookingType: classif.requestedTime ? 'hourly' : 'fullday',
    date: classif.requestedDate || '',
    time: classif.requestedTime || null,
    duration: 2,
    note: classif.notes
      ? `Eredeti e-mail: ${classif.originalSubject}\n\n${classif.notes}`
      : `Eredeti e-mail: ${classif.originalSubject}`,
    source: 'email',
    calendarConflict,
    conflictDetails
  }
}];

const emails = $input.all().map(i => i.json);

if (!emails.length) {
  return [{ json: { skip: true, emailCount: 0 } }];
}

const emailList = emails.map((e, i) =>
  `${i+1}. Feladó: ${e.from || '?'} | Tárgy: ${e.subject || '(nincs)'} | ${(e.text || e.html || '').substring(0, 200).replace(/\n/g, ' ')}`
).join('\n');

const now = new Date();
const timeStr = now.toLocaleString('hu-HU', { timeZone: 'Europe/Budapest' });

const prompt = `Összefoglalás kérés: Az alábbi e-mailek érkeztek az elmúlt 2 órában a Silverframe Studio (info@silverframe.hu) fiókba.

Dátum/idő: ${timeStr}
E-mailek száma: ${emails.length}

${emailList}

Készíts egy rövid (max 8-10 sor) magyar nyelvű összefoglalót:
- Listázd a legfontosabb/érdekes e-maileket bullet pontokban
- Ha van foglalási kérelem, emeld ki félkövérrel
- Ha van sürgős ügy, emeld ki
- Egyéb adminisztratív/spam e-maileket csak egyben: "X db egyéb értesítés"
- Légy tömör és informatív`;

return [{ json: { prompt, emailCount: emails.length, skip: false } }];

const geminiResp = $input.first().json;
const digestData = $('Build Digest Prompt').first().json;

let digestText = '';
try {
  digestText = geminiResp.candidates[0].content.parts[0].text;
} catch(e) {
  digestText = `${digestData.emailCount} db e-mail érkezett az elmúlt 2 órában. Kézzel ellenőrizd az inboxot.`;
}

const now = new Date();
const timeStr = now.toLocaleString('hu-HU', { timeZone: 'Europe/Budapest', hour: '2-digit', minute: '2-digit' });
const dateStr = now.toLocaleDateString('hu-HU', { timeZone: 'Europe/Budapest', year: 'numeric', month: 'long', day: 'numeric' });

const esc = s => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const html = `<!DOCTYPE html><html lang="hu"><head><meta charset="UTF-8"><style>body{font-family:Arial,sans-serif;background:#0b0c10;color:#e8e4dc;padding:20px}.wrap{max-width:580px;margin:0 auto;background:#14151a;border-radius:12px;overflow:hidden}.hdr{background:#1a2a3a;padding:20px 28px;border-bottom:1px solid #2a3a4a}.hdr h1{margin:0;color:#64b5f6;font-size:1rem;font-weight:500}.body{padding:24px}.count{display:inline-block;background:#1a2a3a;color:#64b5f6;padding:4px 12px;border-radius:20px;font-size:.8rem;margin-bottom:16px;border:1px solid #1565c0}.summary{background:#1a1b20;border-radius:8px;padding:18px;color:#c8c4bc;line-height:1.8;font-size:.9rem;white-space:pre-wrap}.ftr{padding:16px 28px;border-top:1px solid #222;font-size:.75rem;color:#555;text-align:center}</style></head><body><div class="wrap"><div class="hdr"><h1>📬 Silverframe Inbox Összefoglaló — ${esc(dateStr)} ${esc(timeStr)}</h1></div><div class="body"><div class="count">${esc(String(digestData.emailCount))} e-mail az elmúlt 2 órában</div><div class="summary">${esc(digestText).replace(/\n/g,'<br>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')}</div></div><div class="ftr">Silverframe Studio · Automatikus 2 órás összefoglaló</div></div></body></html>`;

return [{
  json: {
    toEmail: 'info@silverframe.hu',
    subject: `📬 Inbox összefoglaló — ${digestData.emailCount} e-mail (${timeStr})`,
    html
  }
}];
